import assert from 'node:assert/strict';
import { slugify } from '../src/slugify.js';

const mode = process.argv[2];
const check = (input, expected) => assert.equal(slugify(input), expected, JSON.stringify(input));
if (mode === 'latin') {
  const cases = [
    ['Crème Brûlée', 'creme-brulee'], ['Łódź', 'lodz'],
    ['ÀÁÂÃÄÅ ĀĂĄ ǍǞǠǺ', 'aaaaaa-aaa-aaaa'],
    ['ÇĆĈĊČ ÈÉÊËĒĔĖĘĚ', 'ccccc-eeeeeeeee'],
    ['ÌÍÎÏĨĪĬĮİ ÑŃŅŇ', 'iiiiiiiii-nnnn'],
    ['ÒÓÔÕÖŌŎŐ ǑǪǬ', 'oooooooo-ooo'],
    ['ÙÚÛÜŨŪŬŮŰŲ ÝŸŶ', 'uuuuuuuuuu-yyy'],
    ['Đđ Ðð Þþ Łł Øø Ææ Œœ ßẞ', 'dd-dd-thth-ll-oo-aeae-oeoe-ssss'],
    ['Ħħ ı Ŋŋ ſ Ƒƒ Ŧŧ', 'hh-i-nn-s-ff-tt'],
    ['Ǣǣ Ǽǽ Ǿǿ', 'aeae-aeae-oo'],
    ['ﬀ ﬁ ﬂ ﬃ ﬄ ﬅ ﬆ', 'ff-fi-fl-ffi-ffl-st-st'],
    ['Straße smørrebrød encyclopædia œuvre', 'strasse-smorrebrod-encyclopaedia-oeuvre'],
    ['Tiếng Việt — Dvořák — İstanbul', 'tieng-viet-dvorak-istanbul'],
    ['a\u0301b e\u0300\u0302x n\u0303o', 'ab-ex-no'],
    ['a\u1ab0b e\u1dc0f o\u20d7p u\ufe20v', 'ab-ef-op-uv'],
    ['Crème Ελληνικά Łódź Йога', 'creme-ελληνικά-lodz-йога'],
    ['a\u0301/東京/ø/ά/Й', 'a-東京-o-ά-й'],
  ];
  for (const [input, expected] of cases) {
    check(input, expected);
    if (!/[\p{Script=Greek}\p{Script=Cyrillic}]/u.test(input)) check(input.normalize('NFD'), expected);
  }
} else if (mode === 'decomposable') {
  let count = 0;
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const letter = String.fromCodePoint(cp);
    if (!/^\p{Script=Latin}$/u.test(letter) || !/^\p{L}$/u.test(letter)) continue;
    const decomposed = letter.toLowerCase().normalize('NFD');
    if (!/^[a-z]\p{M}+$/u.test(decomposed)) continue;
    const expected = decomposed[0];
    check(letter, expected);
    check(decomposed, expected);
    check(`x${letter}y`, `x${expected}y`);
    check(`x${decomposed}y`, `x${expected}y`);
    count++;
  }
  assert.ok(count > 400, `Only tested ${count} letters`);
} else if (mode === 'preserve') {
  const baseline = text => text.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-+|-+$/g, '');
  const examples = [
    '', '  --Release 2.0--  ', 'Hello, World!', 'A___B...C', '123 ٤٥٦ １２３',
    'Привет мир', 'Йога Ёлка Ї Є Ӑ Ӧ', 'Ελληνικά ΆΈΉΊΌΎΏ ΐΰ',
    '東京 日本語 カタカナ ひらがな', '中文 한국어 한글', 'עברית العربية فارسی',
    'हिन्दी বাংলা தமிழ் ไทย', 'ԱԲԳ აბგ', '😀Hello🌍WORLD🚀',
    'α\u0301 β\u0308', 'и\u0306 е\u0308', 'a/b\\c : d+e @f #g',
    '𝔄 𝕭 𝖈 Ⅳ ① ²', '\u0301hello\u0301',
  ];
  for (const input of examples) check(input, baseline(input));
  // Cover each non-Latin Unicode letter, including accented letters and
  // scripts outside the BMP. No global normalization may alter these.
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const letter = String.fromCodePoint(cp);
    if (!/^\p{L}$/u.test(letter) || /^\p{Script=Latin}$/u.test(letter)) continue;
    check(letter, baseline(letter));
  }
} else {
  throw new Error(`Unknown check mode: ${mode}`);
}
console.log(`Passed ${mode}`);
